  add("Password autocomplete configuration", "Настройка автозаполнения пароля", "Configuración de autocompletado de contraseña", "Passwort-Autocomplete-Konfiguration", "Configuration d’autocomplétion du mot de passe", "パスワードのオートコンプリート設定", "Configuração de preenchimento automático da senha", "密码自动填充配置");
  add("Error messages are associated with fields", "Сообщения об ошибках связаны с полями", "Los mensajes de error están asociados a los campos", "Fehlermeldungen sind den Feldern zugeordnet", "Les messages d’erreur sont associés aux champs", "エラーメッセージがフィールドに関連付けられている", "As mensagens de erro estão associadas aos campos", "错误信息与字段相关联");
  add("Fields can receive focus and input", "Поля могут получить фокус и ввод", "Los campos pueden recibir foco y texto", "Felder können Fokus und Eingabe erhalten", "Les champs peuvent recevoir le focus et une saisie", "フィールドがフォーカスと入力を受け取れる", "Os campos podem receber foco e entrada", "字段可以获得焦点并输入");
